import { sql } from "drizzle-orm";
import {
  bigserial,
  boolean,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  varchar,
} from "drizzle-orm/pg-core";

/**
 * ════════════════════════════════════════════════════════════════════════════
 *  Meridian — canonical data model
 * ════════════════════════════════════════════════════════════════════════════
 *  Conventions
 *   • Every table uses a UUID primary key generated by the database
 *     (`gen_random_uuid()`, pgcrypto/PG13+).
 *   • Timestamps are `timestamptz` — the DB stores UTC, the UI localises.
 *   • Soft deletes are modelled explicitly (`archived_at`, `deactivated_at`)
 *     so performance history is never destroyed.
 *   • Free-text that can contain sensitive personal commentary is stored with
 *     application-level AES-256-GCM (`*_enc` columns).
 *   • All composite/foreign key columns are indexed for the reads the product
 *     actually performs.
 */

