/**
 * The goal-setting approval workflow, deliberately separate from the progress
 * `status` above. Step 1–2 of the review process: an employee finalises goals
 * (`DRAFT`), sends them to their manager (`SUBMITTED`), and the manager either
 * approves them (`APPROVED`) or sends them back with a reason (`RETURNED`).
 */
export const goalApprovalEnum = pgEnum("goal_approval_status", [
  "DRAFT",
  "SUBMITTED",
  "APPROVED",
  "RETURNED",
]);

