/* ───────────────────────────── Inferred types ─────────────────────────── */

export type User = typeof users.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type Department = typeof departments.$inferSelect;
export type Session = typeof sessions.$inferSelect;
export type ReviewCycle = typeof reviewCycles.$inferSelect;
export type CycleParticipant = typeof cycleParticipants.$inferSelect;
export type Review = typeof reviews.$inferSelect;
export type Goal = typeof goals.$inferSelect;
export type Task = typeof tasks.$inferSelect;
export type Feedback = typeof feedback.$inferSelect;
export type OneOnOne = typeof oneOnOnes.$inferSelect;
export type AuditEvent = typeof auditEvents.$inferSelect;
export type Notification = typeof notifications.$inferSelect;
export type ReviewTemplate = typeof reviewTemplates.$inferSelect;
export type TemplateCompetency = typeof templateCompetencies.$inferSelect;
export type Competency = typeof competencies.$inferSelect;
export type RatingScale = typeof ratingScales.$inferSelect;
export type RatingScaleLevel = typeof ratingScaleLevels.$inferSelect;
export type SystemRole = (typeof systemRoleEnum.enumValues)[number];
export type GoalStatus = (typeof goalStatusEnum.enumValues)[number];
export type ReviewStatus = (typeof reviewStatusEnum.enumValues)[number];
export type CycleStatus = (typeof cycleStatusEnum.enumValues)[number];
